  ...((cfg.llm || {}).json_mode ? { response_format: { type: 'json_object' } } : {}), messages });
function brandLines() {
  const b = cfg.brand || {};
  return [`Бренд: ${b.name || ''}. ${b.about || ''}`, `Аудитория: ${b.audience || ''}`, `Голос: ${b.voice || ''}`,
    ...(b.rules || []).map((r) => `- ${r}`)].join('\n');
}
const table = planTable($input.first().json.values);
const now = nowMs();
const late = (cfg.max_late_hours || 12) * 60 * MIN;
const missed = [];
const due = [];
for (const r of table.rows) {
  if (r.post.status !== 'approved') continue;
  const at = whenOf(r.post.publish_at);
  if (Number.isNaN(at) || !(cfg.channels || {})[r.post.channel]) { missed.push({ r, reason: Number.isNaN(at) ? 'не понял дату' : 'канал не настроен' }); continue; }
  if (at !== null && at > now) continue;
  if (at !== null && now - at > late) { missed.push({ r, reason: `время публикации ${stamp(at)} прошло больше ${cfg.max_late_hours || 12} ч назад` }); continue; }
  due.push({ r, at: at || 0 });
}
const data = missed.map(({ r, reason }) => botWrite(r.sheetRow, Object.assign({}, r.post, { status: 'failed', error: reason })));
const base = { kind: 'none', chat: cfg.approval_chat_id, fix: missed.length > 0, fix_http: missed.length ? batchUpdate(data) : null,
  fix_text: missed.length ? ['Не опубликовано:', ...missed.map(({ r, reason }) => `• «${r.post.topic.slice(0, 80)}» (${r.post.channel}) — ${reason}`), 'Поставьте новую дату и статус approved, если публикация ещё нужна.'].join('\n') : '' };
if (!due.length) return [{ json: base }];
due.sort((a, b) => a.at - b.at);
const { r } = due[0];
const post = r.post;
const ch = cfg.channels[post.channel];
const text = post.final || post.draft;
const lock = Object.assign({}, post, { status: 'publishing', error: '' });
const out = Object.assign(base, { kind: ch.type, id: post.id, sheet_row: r.sheetRow, post: lock, channel: post.channel,
  // Marked "publishing" before the call: if the run breaks after publishing, the post is not published twice.
  lock_http: batchUpdate([botWrite(r.sheetRow, lock)]) });

function html(md) {
  const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const inline = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2">$1</a>');
  return md.split(/\n{2,}/).map((block) => {
    const lines = block.split('\n');
    const h = /^(#{2,4})\s+(.*)$/.exec(block.trim());
    if (h && lines.length === 1) return `<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;
    if (lines.every((l) => /^\s*[-•*]\s+/.test(l))) return '<ul>' + lines.map((l) => `<li>${inline(l.replace(/^\s*[-•*]\s+/, ''))}</li>`).join('') + '</ul>';
    if (lines.every((l) => /^\s*\d+[.)]\s+/.test(l))) return '<ol>' + lines.map((l) => `<li>${inline(l.replace(/^\s*\d+[.)]\s+/, ''))}</li>`).join('') + '</ol>';
    return `<p>${lines.map(inline).join('<br>')}</p>`;
  }).join('\n');
}
if (ch.type === 'telegram') {
  const photo = /^https?:\/\//.test(post.image_url) ? post.image_url : '';
  const short = text.length <= 1024;
  out.telegram = { chat: ch.chat_id, photo, caption: photo && short ? text : '', text, text_after: Boolean(photo) && !short };
} else if (ch.type === 'wordpress') {
  const image = /^https?:\/\//.test(post.image_url) ? `<p><img src="${post.image_url.replace(/"/g, '%22')}" alt=""></p>\n` : '';
  out.request = { url: String(ch.url).replace(/\/$/, '') + '/wp-json/wp/v2/posts', body: { title: post.title || post.topic, content: image + html(text), status: ch.status || 'draft' } };
} else if (ch.type === 'webhook') {
  out.request = { url: ch.url, body: { id: post.id, channel: post.channel, title: post.title || post.topic, text, image_url: post.image_url || '', topic: post.topic, publish_at: stamp(due[0].at || now) } };
} else out.kind = 'none';
return [{ json: out }];

